interface SkeuoMatrixGridProps {
  go: (view: ViewId) => void
  onOpenExplorer: () => void
  safeT?: (key: string, fallback: string) => string
}

export default function SkeuoMatrixGrid({
  go,
  onOpenExplorer,
  safeT = (_k, fallback) => fallback,
}: SkeuoMatrixGridProps) {
  const handleFileManagerClick = (e: React.MouseEvent) => {
    const target = e.target as HTMLElement
    // Tombol 3 titik di File Manager membuka Sub Menu Storage & Files (FilesView)
    if (target.closest("#btn-dot3-fm") || target.closest(".btn-dot3-interactive")) {
      e.stopPropagation()
      go("files")
      return
    }
    // Klik area bodi kartu mengeksekusi perintah dari pengaturan Options (file manager click action)
    onOpenExplorer()
  }

  return (
    <nav
      aria-label="Fitur MyServer"
      className="w-[252px] h-[228px] mx-auto grid grid-cols-2 gap-x-[8px] gap-y-[8px] select-none"
    >
      {/* Slot 1 (Baris 1 - Kiri): BACKUP */}
      <div
        data-crt-slot="backup"
        className="card-container w-[122px] h-[110px] select-none relative cursor-pointer overflow-visible"
        role="button"
        tabIndex={0}
        onClick={(e) => {
          const target = e.target as HTMLElement
          if (target.closest(".btn-dot3-standby") || target.closest(".btn-dot3-interactive")) {
            e.stopPropagation()
            return
          }
          go("backup")
        }}
        onKeyDown={(e) => {
          if (e.key === "Enter" || e.key === " ") {
            e.preventDefault()
            go("backup")
          }
        }}
        title={safeT("feat_backup_sub", "Atomic Backup & Syncthing")}
        dangerouslySetInnerHTML={{ __html: BACKUP_SVG }}
      />

      {/* Slot 2 (Baris 1 - Kanan): FILE MANAGER */}
      <div
        data-crt-slot="files"
        className="card-container w-[122px] h-[110px] select-none relative cursor-pointer overflow-visible"
        role="button"
        tabIndex={0}
        onClick={handleFileManagerClick}
        onKeyDown={(e) => {
          if (e.key === "Enter" || e.key === " ") {
            e.preventDefault()
            onOpenExplorer()
          }
        }}
        title={safeT("feat_storage_sub", "Penyimpanan SMB & Web Files")}
        dangerouslySetInnerHTML={{ __html: FILES_SVG }}
      />

      {/* Slot 3 (Baris 2 - Kiri): APPS */}
      <div
        data-crt-slot="apps"
        className="card-container w-[122px] h-[110px] select-none relative cursor-pointer overflow-visible"
        role="button"
        tabIndex={0}
        onClick={(e) => {
          const target = e.target as HTMLElement
          if (target.closest(".btn-dot3-standby") || target.closest(".btn-dot3-interactive")) {
            e.stopPropagation()
            return
          }
          go("apps")
        }}
        onKeyDown={(e) => {
          if (e.key === "Enter" || e.key === " ") {
            e.preventDefault()
            go("apps")
          }
        }}
        title={safeT("feat_apps_sub", "Layanan & Web Apps")}
        dangerouslySetInnerHTML={{ __html: APPS_SVG }}
      />

      {/* Slot 4 (Baris 2 - Kanan): OPTIONS */}
      <div
        data-crt-slot="options"
        className="card-container w-[122px] h-[110px] select-none relative cursor-pointer overflow-visible"
        role="button"
        tabIndex={0}
        onClick={(e) => {
          const target = e.target as HTMLElement
          if (target.closest(".btn-dot3-standby") || target.closest(".btn-dot3-interactive")) {
            e.stopPropagation()
            return
          }
          go("settings")
        }}
        onKeyDown={(e) => {
          if (e.key === "Enter" || e.key === " ") {
            e.preventDefault()
            go("settings")
          }
        }}
        title={safeT("feat_settings_sub", "Pengaturan & Preferensi Sistem")}
        dangerouslySetInnerHTML={{ __html: OPTIONS_SVG }}
      />
    </nav>
  )
}
